async function mediaRunB(){
  if(mediaBBusy||mediaCBusy||!mediaBCanRun())return;
  mediaBBusy=true;renderMediaPreview();
  const client=cloudClient,owner=cloudUser.id;
  let original=state,before=JSON.stringify(state);
  // Session refresh events are fine; a different owner/client or any record change aborts.
  const guard=()=>mediaBCanRun()&&state===original&&JSON.stringify(state)===before&&
    cloudClient===client&&cloudUser?.id===owner;
  try{
    if(!await mediaBConfirm())return;
    mediaBStatus("Cloud 확인이 끝나기를 기다리는 중…");
    if(!await mediaBWaitIdle())throw Error("Cloud 확인이 끝나지 않았습니다. 잠시 후 다시 눌러 주세요.");
    // Baseline is taken after confirm + idle so a focus check during the dialog is not a conflict.
    if(state!==original&&cloudClient===client&&cloudUser?.id===owner){original=state;before=JSON.stringify(state)}
    if(!guard())throw Error("확인 중 계정·기록·Cloud 상태가 변경됐습니다.");
    const auth=await client.auth.getUser();
    if(auth.error||auth.data?.user?.id!==owner||!guard())throw Error("소유 계정 로그인을 확인하지 못했습니다.");
    const result=await window.HANI_MEDIA.prepareB({
      state:JSON.parse(before),client,userId:owner,guard,progress:mediaBStatus,
      snapshot:async()=>{
        const full=await window.HANI_MEDIA.reembed(JSON.parse(before));
        if(!full?.complete||!full.data||!guard())return false;
        return await cloudSaveSafetySnapshot("before_media_stage_b",full.data);
      }
    });
    if(!result.ok)throw Error(result.error);
    await mediaBWaitIdle();
    const verifiedAuth=await client.auth.getUser();
    if(verifiedAuth.error||verifiedAuth.data?.user?.id!==owner||!guard())
      throw Error("최종 소유 계정·기록 검증에 실패했습니다.");
    mediaBStatus("d · 검증된 참조를 한 번 저장 · 기록의 원본 이미지는 그대로");
    const candidate=structuredClone(original);
    for(const change of result.changes){
      const row=candidate[change.kind][change.index];
      if(row.id!==change.id||row[change.field]!==change.data||row[change.field+"Ref"])
        throw Error("참조 추가 직전 기록이 달라졌습니다.");
      row[change.field+"Ref"]=change.ref;
    }
    if(result.changes.length){
      state=candidate; // One mutation, then the existing normal save/Cloud queue.
      let saved=false;
      try{saved=save()?.ok===true}
      finally{if(!saved)state=original}
      if(!saved)throw Error("기존 저장 경로에서 저장하지 못했습니다. 참조 추가를 중단했습니다.");
      try{renderAll()}catch(_){toast("참조는 저장됐습니다. 화면을 새로 확인해 주세요.")}
    }
    mediaBStatus("완료 · "+result.count+"장 보관 확인 · 기록의 원본 이미지는 그대로 · 충돌 "+
      result.conflicts.length+"건"+(result.conflicts.length?" (기존 참조 보존)":""));
  }catch(error){mediaBStatus("중단 · "+(error?.message||"이중 보관 실패"))}
  finally{mediaBBusy=false;renderMediaPreview()}
}
let mediaCBusy=false,mediaCEligibility=null;
function mediaCBlockedReason(){
  if(!window.HANI_MEDIA)return "이미지 보관 기능을 불러오지 못했어요.";
  if(!cloudClient||!cloudUser?.id||!cloudAutoSyncReady||cloudRuntime.sync!=="ON")
    return "Cloud 로그인/동기화가 꺼져 있어요.";
  if(navigator.onLine===false)return "인터넷 연결을 확인해 주세요.";
  if(!mediaBCanRun())return "기록 복구·가져오기가 끝난 뒤 다시 눌러 주세요.";
  // mediaHasRefs is for already-separated images; B leaves both inline and ref.
  if(![["books","cover"],["movies","poster"]].some(([kind,field])=>
    Array.isArray(state?.[kind])&&state[kind].some(row=>row?.[field+"Ref"]&&
      typeof row[field]==="string"&&row[field].startsWith("data:"))))
    return "분리할 내장 이미지가 없어요. 먼저 B단계 이중 보관을 실행해 주세요.";
  return "";
}
function mediaCEligibilityReason(error){
  const message=error?.message||"이미지 보관 상태를 확인하지 못했어요.";
  if(message==="기기에 검증된 참조 이미지가 없습니다.")
    return "이 기기에 이미지 사본을 저장·확인하지 못했어요(브라우저 저장공간).";
  if(message==="Cloud 이미지 보관 목록이 누락됐습니다.")
    return "Cloud 보관함 목록을 확인하지 못했어요.";
  return message;
}
