function cloudDecodeJwtRole(key){
  try{
    const parts=key.split(".");
    if(parts.length!==3)return "";
    const body=parts[1].replace(/-/g,"+").replace(/_/g,"/");
    const padded=body+"=".repeat((4-body.length%4)%4);
    return JSON.parse(atob(padded)).role||"";
  }catch(e){return ""}
}
