    q('[data-exam-prev]', examDialog).disabled = index === 0;
    q('[data-exam-next]', examDialog).disabled = index === quiz.questions.length - 1;
    q('[data-exam-submit]', examDialog).disabled = answered !== quiz.questions.length;
